import React, {Suspense, lazy} from 'react';
import { BrowserRouter, Route, Switch } from 'react-router-dom';

const MainHeader = lazy(()=>import('./layouts/header/MainHeader'));
const BoardList = lazy(()=>import('./layouts/board/BoardListLayer'));
const BoardViewer = lazy(()=>import('./layouts/board/BoardViewerLayer'));

function App() {
  return (
    <BrowserRouter>
      <Suspense fallback={<div>Loading...</div>}>
        <MainHeader/>
        <Switch>
          <Route exact path="/"><BoardList/></Route>
          <Route exact path="/boards/:paper"><BoardViewer/></Route>
        </Switch>
        
      </Suspense>
    </BrowserRouter>
  );
}

export default App;
